"""Fixed MNIST composition check; invoke existing construction and evaluation entries."""
import copy, json, os, subprocess, sys, time
from pathlib import Path
import torch
from _impl.io import digest, save_json
from _impl.models import apply, load_checkpoint

folder = Path('results/comparison/params_composition')
plan = json.loads((folder / 'protocol.json').read_text())
root = Path(plan['output'])
started = time.time()
def call(module, *args):
    subprocess.run([sys.executable, '-u', '-m', module, *map(str, args)], check=True)
def refresh(cfg):
    cfg['source_sha256'] = {p: digest(p) for p in cfg['source_sha256']}
def evaluate(cfg, path):
    refresh(cfg); save_json(path, cfg)
    for i, case in enumerate(cfg['cases']):
        for pilot in [True, False]:
            call('experiment.main_table', '--protocol', path, '--case', i, *(['--pilot'] if pilot else []))
            stage = 'pilot' if pilot else 'full'
            call('experiment.main_table', '--verify', Path(cfg['output']) / stage / f'{i:02d}_MNIST_SVHN')

# Complete the already-running evaluation before using its GPU.
finished = Path('outputs/unmask_current_20261103/resumed/full/independent_validation.json')
while not finished.exists():
    if time.time() - started > 3600:
        raise RuntimeError('Prior evaluation did not finish; no new GPU stage started')
    time.sleep(20)

for name, ref in plan['publications'].items():
    call('experiment.construct', '--method', 'params', '--target', 'MNIST',
         '--protocol', folder / 'construct.json', '--publication', ref['path'],
         '--publication-sha256', ref['sha256'], '--output', root / name / 'publication')
parent = json.loads(Path('results/comparison/unmask_current/evaluation.json').read_text())
refresh(parent); save_json(root / 'parent.json', parent)
for name in plan['publications']:
    publication = root / name / 'publication/release.pt'
    call('experiment.recover', '--target', 'MNIST', '--method', 'aga', '--aligned-reference',
         '--protocol', root / 'parent.json', '--publication', publication,
         '--sha256', digest(publication), '--output', root / name / 'AGA')

cfg = copy.deepcopy(parent)
cfg['tasks'] = {k: cfg['tasks'][k] for k in ['MNIST', 'SVHN']}
cfg['TA_coefficient'] = .5; cfg['mergers'] = ['TA']; cfg['attack_scopes'] = ['None', 'Protected expert', 'All experts']
cfg['defenses'] = {}
for name in plan['publications']:
    cfg['defenses'][name + '_PaRaMS'] = {'release': {'path': str(root / name / 'publication/release.pt'), 'sha256': digest(root / name / 'publication/release.pt')},
        'AGA_edits': {'path': str(root / name / 'AGA/edits.pt'), 'sha256': digest(root / name / 'AGA/edits.pt')}}
cfg['cases'] = [dict(target='MNIST', partner='SVHN', defenses=list(cfg['defenses']))]
cfg['legacy'] = {}
# Reuse the existing matched clean scores; each frozen model is replayed by verify.
old = Path('outputs/finite_classification_20261102/MNIST/evaluation/full/00_MNIST_SVHN/artifacts/predictions.pt')
cfg['legacy']['MNIST_SVHN/Unprotected'] = {stage: {'path': str(old), 'sha256': digest(old), 'key_template': key}
    for stage,key in [('standalone','Unprotected/Standalone/None/{task}'),('direct','Unprotected/TA/None/{task}'),
                      ('AGA_target_only','Unprotected/TA/Protected expert/{task}'),('AGA_both','Unprotected/TA/All experts/{task}')]}
cfg['output'] = str(root / 'evaluation')
cfg['experiment'] = 'Existing PaRaMS composed with fixed current defenses; no new defense optimizer'
evaluate(cfg, root / 'evaluation.json')

# Same previously fixed ProDistill data, initialization, coefficient kernel and budget.
dist = json.loads(Path('results/attack_generalization_20261028/prodistill/protocol.json').read_text())
dist['output'] = str(root / 'prodistill'); dist['cases'] = [dist['cases'][0]]
dist['cases'][0]['releases'] = {n: s['release'] for n,s in cfg['defenses'].items()}
refresh(dist); save_json(root / 'prodistill.json', dist)
call('experiment.distill', '--prodistill', '--protocol', root / 'prodistill.json')

# Known-module recovery, and the same recovery after AGA, are separate comparisons.
for after_aga in [False, True]:
    reset = copy.deepcopy(cfg); reset['attack_scopes'] = ['None']; reset['legacy'] = {}
    reset['output'] = str(root / ('AGA_then_reset' if after_aga else 'reset'))
    reset['cases'] = [dict(target='MNIST', partner='SVHN', defenses=['Defense1_PaRaMS'], published_bias_projection=True),
                      dict(target='MNIST', partner='SVHN', defenses=['Defense2_PaRaMS'], public_replacement=dict(layer=11, side='B+b'))]
    if after_aga:
        original = load_checkpoint('MNIST/finetuned.pt')
        aligned = apply(original, parent['AGA_references']['MNIST'], full=True)
        reset['defenses']['Unprotected'] = {'release': parent['AGA_references']['MNIST'], 'full_state': True}
        for name,spec in cfg['defenses'].items():
            model = apply(aligned, spec['AGA_edits']); path = root / (name + '_AGA.pt')
            torch.save(model.state_dict(), path)
            reset['defenses'][name] = {'release': {'path': str(path), 'sha256': digest(path)}, 'full_state': True}
        del aligned, original, model
    evaluate(reset, root / ('AGA_then_reset.json' if after_aga else 'reset.json'))
save_json(root / 'completed.json', dict(status='all_fixed_stages_completed', new_defense_points=2,
    new_AGA_calls=2, new_coefficient_backward_steps=2400, expert_training_updates=0, new_output_calibration=False))
print('COMPOSITION_COMPLETED', flush=True)
